    STEP_COUNTS.with_borrow_mut(|c|{
        c.sequence+=1;c.counts[kind][0]+=1;
        if free{c.counts[kind][1]+=1;}
        if let Some(previous)=c.free.get(&key).copied(){
            c.counts[kind][2]+=1;
            if free{c.counts[kind][3]+=1;
                for (slot,span) in [64,256,1024,4096].into_iter().enumerate(){if c.sequence-previous<=span{c.counts[kind][4+slot]+=1;}}
            }
        }
